    """Workspace-relative POSIX path, so `./a.py`, `a.py` and `/ws/a.py` compare equal."""
    p = str(path).strip()
    if os.path.isabs(p) and cwd:
        for root in dict.fromkeys((cwd, os.path.realpath(cwd))):
            root = root.rstrip("/")
            if p.startswith(root + "/"):
