    ]
    keyword_by_id = {e["id"]: e["predicted_tier"] for e in comparison.results["keyword_rule"]["holdout"].task_evaluations}
    for item in comparison.results["naive_bayes"]["holdout"].task_evaluations:
        if not item["correct_tier"]:
